<?php
namespace App\Domain\ApiHub;use App\Domain\ApiHub\Models\TenantApiWebhookDelivery;use App\Services\ApiHub\Webhooks\WebhookUrlGuard;use Illuminate\Support\Facades\Http;
final class ApiWebhookDeliveryService{public function __construct(private WebhookUrlGuard$guard){}public function deliver(TenantApiWebhookDelivery$delivery):void{$d=TenantApiWebhookDelivery::with('endpoint')->whereKey($delivery->id)->lockForUpdate()->firstOrFail();if(!in_array($d->status,['PENDING','RETRY'],true)||!$d->endpoint||$d->endpoint->status!=='ACTIVE')return;$max=config('zigo_api_hub.webhook_max_attempts',6);$attempt=$d->attempt+1;$timestamp=now()->timestamp;$json=json_encode($d->payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);try{$this->guard->assertAllowed($d->endpoint->url,app()->environment(['local','testing'])?'sandbox':'production');$signature='sha256='.hash_hmac('sha256',$d->event_id.'.'.$timestamp.'.'.$json,$d->endpoint->secret());$response=Http::timeout(8)->withHeaders(['Content-Type'=>'application/json','X-ZIGO-Event-Id'=>$d->event_id,'X-ZIGO-Timestamp'=>$timestamp,'X-ZIGO-Signature'=>$signature])->withBody($json,'application/json')->post($d->endpoint->url);if($response->successful()){$d->update(['attempt'=>$attempt,'status'=>'DELIVERED','http_status'=>$response->status(),'delivered_at'=>now(),'next_retry_at'=>null,'last_error_safe'=>null]);$d->endpoint->update(['last_delivery_at'=>now()]);return;}$error='HTTP '.$response->status();$status=$attempt>=$max?'EXHAUSTED':'RETRY';$d->update(['attempt'=>$attempt,'status'=>$status,'http_status'=>$response->status(),'next_retry_at'=>$status==='RETRY'?now()->addMinutes(2**min($attempt,6)):null,'last_error_safe'=>$error]);}catch(\Throwable$e){$status=$attempt>=$max?'EXHAUSTED':'RETRY';$d->update(['attempt'=>$attempt,'status'=>$status,'next_retry_at'=>$status==='RETRY'?now()->addMinutes(2**min($attempt,6)):null,'last_error_safe'=>'Entrega no disponible']);}}}
